{
  "url": "https://www.predsci.com/~pete/research/wsa-sw-manuscript/riley-wsa-sw-v4.pdf",
  "prompt": "Quote verbatim every empirical solar wind speed equation in this manuscript (WSA forms, DCHB forms, any attributed to Arge et al. 2003, 2004, McGregor 2011), with all numerical coefficients (e.g., 285, 625, 2/9, 0.8, w, beta, exponent 3), the radius at which applied, and any statements about the coefficients' provenance. Also any statement of the journal/volume."
}

{
  "query": "\"On the role played by magnetic expansion factor in the prediction of solar wind speed\" Riley Linker Arge Space Weather 2015 equation",
  "mode": "standard"
}

{
  "url": "https://en.wikipedia.org/wiki/Wang%E2%80%93Sheeley%E2%80%93Arge_model",
  "prompt": "Quote verbatim all velocity equations and coefficients, with the paper each is attributed to (Arge 2003, Arge 2004, McGregor 2011, Riley 2015, etc.)."
}

{
  "url": "https://en.wikipedia.org/wiki/Wang–Sheeley–Arge_model",
  "prompt": "Quote verbatim all velocity equations and coefficients, with the paper each is attributed to (Arge 2003, Arge 2004, McGregor 2011, Riley 2015, etc.)."
}

{
  "url": "https://arxiv.org/abs/1905.04353",
  "prompt": "Give title, authors, journal reference/DOI."
}

{
  "query": "Reiss 2020 ApJ 891 165 \"Forecasting the Ambient Solar Wind with Numerical Models. II\" adaptive prediction WSA coefficients arxiv",
  "mode": "standard"
}

{
  "url": "https://ar5iv.labs.arxiv.org/html/1905.04353",
  "prompt": "Quote verbatim the WSA velocity equation(s) used, including all coefficient values (e.g., 285, 625, 2/9, w, beta, 0.8, exponent 3), any table of coefficients, which papers they cite for the form (Arge 2003/2004, McGregor 2011, Riley 2015), the radius at which the WSA speed is computed (source surface vs 5 Rs vs 21.5 Rs), and any optimized coefficient values reported. Also the journal volume and article number."
}

{
  "url": "https://ar5iv.labs.arxiv.org/html/2003.09336",
  "prompt": "Quote verbatim the WSA velocity equation, the list of coefficients and their default values and ranges used for the ensemble, the sensitivity ranking result (which coefficients matter most/least), and the selected optimum coefficient values or how they vary in time, plus reported skill improvements (e.g., MAE, RMSE values, vs default). Also any mention of STEREO in situ data."
}

{
  "url": "https://ar5iv.labs.arxiv.org/html/1905.04353",
  "prompt": "Quote the exact sentence listing the coefficient values for the WSA equation (v0, v1, alpha, beta, gamma, w, delta) character-for-character, and the equations for WS and DCHB relations with their coefficients. Also, what is the outer exponent on the brace in the WSA equation (is it literal 3 or a symbol)? And the units of w (degrees?)."
}

{
  "url": "https://agupubs.onlinelibrary.wiley.com/doi/full/10.1002/2014SW001144",
  "prompt": "Quote verbatim the WSA velocity equation and coefficient values (285, 625, 2/9, w, beta), and the WS and DCHB equations with coefficients."
}

{
  "query": "Riley Linker Arge 2015 WSA \"285\" \"625\" \"2/9\" \"w = 2\" degrees β expansion factor DCHB comparison",
  "mode": "extended"
}

{
  "url": "https://agupubs.onlinelibrary.wiley.com/doi/pdfdirect/10.1002/2014SW001144",
  "prompt": "Quote verbatim the WSA, WS and DCHB velocity equations and the coefficient values used (e.g., 285, 625/910, 2/9, w, beta/delta, gamma 0.8), with units."
}

{
  "url": "https://www.predsci.com/~pete/research/wsa-sw-manuscript/response-to-reviewer-2.pdf",
  "prompt": "Quote any WSA velocity equation or coefficient values (285, 625, 910, 2/9, w, delta, beta, 0.8, exponent 3) mentioned."
}

{
  "url": "https://link.springer.com/article/10.1007/s11207-019-1576-6",
  "prompt": "Give title, authors, journal, volume, article number, year. Quote verbatim the WSA velocity equation and coefficient values used (and where it is applied, e.g., 5 Rs or 21.5 Rs), and anything about WSA version (v4, v5) coefficients."
}

{
  "url": "https://arxiv.org/pdf/2509.20575",
  "prompt": "Quote verbatim any WSA velocity equation and coefficient values used (V0=285, V1=625, α, β, w), with attribution (Riley 2015? Arge?), and where applied. Also authors/title."
}

